import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

// Middleware: extract user from JWT (simplified)
function authMiddleware(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.user = { id: payload.sub, role: payload.role };
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
  next();
}

// Search endpoint with flexible filtering
app.get('/api/documents/search', authMiddleware, async (req, res) => {
  const { q, category, sort_by, order } = req.query;

  // Build search query
  let baseQuery = `SELECT id, title, content_preview, category, created_at 
                   FROM documents WHERE owner_id = $1`;
  const params = [req.user.id];
  let paramIdx = 2;

  if (q) {
    baseQuery += ` AND (title ILIKE $${paramIdx} OR content_preview ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort - validated against allowlist... or so we think
  const allowedSorts = ['created_at', 'title', 'category'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;
  baseQuery += ` LIMIT 50`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Export endpoint - generates CSV
app.get('/api/documents/export', authMiddleware, async (req, res) => {
  const { format, fields } = req.query;

  // User can select which fields to export
  const requestedFields = fields ? fields.split(',') : ['id', 'title', 'category'];

  // Build column list from user input
  const columnList = requestedFields.map(f => f.trim()).join(', ');

  const query = `SELECT ${columnList} FROM documents WHERE owner_id = $1 ORDER BY created_at DESC LIMIT 1000`;

  try {
    const result = await pool.query(query, [req.user.id]);

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      const header = requestedFields.join(',') + '\n';
      const rows = result.rows.map(r => requestedFields.map(f => r[f.trim()]).join(',')).join('\n');
      res.send(header + rows);
    } else {
      res.json({ documents: result.rows });
    }
  } catch (e) {
    console.error('Export error:', e.message);
    res.status(500).json({ error: 'export failed' });
  }
});

// Admin analytics endpoint
app.get('/api/admin/stats', authMiddleware, async (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }

  const { group_by, date_from } = req.query;
  const groupCol = group_by || 'category';

  // Note: group_by is not validated
  const query = `SELECT ${groupCol}, COUNT(*) as doc_count FROM documents WHERE created_at > $1 GROUP BY ${groupCol}`;

  try {
    const result = await pool.query(query, [date_from || '2024-01-01']);
    res.json({ stats: result.rows });
  } catch (e) {
    console.error('Stats error:', e.message);
    res.status(500).json({ error: 'stats failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
